} | {
    reason: 'input-blur';
    event: FocusEvent;
} | {
    reason: 'input-paste';
    event: ClipboardEvent;
} | {
    reason: 'keyboard';
    event: KeyboardEvent;
} | {
    reason: 'increment-press';
    event: PointerEvent | MouseEvent | TouchEvent;
} | {
    reason: 'decrement-press';
    event: PointerEvent | MouseEvent | TouchEvent;
} | {
    reason: 'wheel';
    event: WheelEvent;
