    event: PointerEvent;
} | {
    reason: 'none';
    event: Event;
}) & {
    cancel: () => void;
    allowPropagation: () => void;
    isCanceled: boolean;
    isPropagationAllowed: boolean;
    trigger: Element | undefined;
    direction?: Direction;
};

